(function() {
    'use strict';

    class InnovationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Motor de Innovación';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    number: 1,
                    title: 'Portfolio Diagnosis',
                    description: '<strong>Diagnóstico del Portafolio</strong><br><br>El Innovation Committee de Grupo Buen Gusto debe evaluar el portafolio actual de 23 proyectos. Actualmente: 78% H1, 18% H2, 4% H3. Weighted Average Horizon Score: 1.26 (target: ≥1.80). <br><br>Decisión 1: ¿Cuántos de los 7 proyectos zombie eliminar? (Rango: 0-7)<br><br>Decisión 2: El VP de BG Foods resiste la eliminación. ¿Cómo responde?'
                },
                {
                    number: 2,
                    title: 'H3 Bet & Ambidexterity',
                    description: '<strong>La Apuesta por H3</strong><br><br>Buen Gusto lanza BGLabs — una unidad dedicada a innovación radical (modelos de negocio digitales, DTC, suscripción).<br><br>Decisión 3: Modelo de ambidestreza para BGLabs (estructura separada / integrada con ringfence / contextual 20% time)<br><br>Decisión 4: Reporting structure (CIO / CEO / External Innovation Committee)<br><br>Decisión 5: Primer concepto H3 (personalización nutrición / ingredients marketplace / wellness DTC)'
                },
                {
                    number: 3,
                    title: 'MVP & Stage-Gate',
                    description: '<strong>MVP y Decisión Stage-Gate</strong><br><br>Para el concepto H3 elegido, diseñar el MVP experiment. Los resultados: 2.1% conversion vs 4.5% target. <br><br>Decisión 6: Diseño del MVP (landing page / producto mínimo / alianza Mercado Libre)<br><br>Decisión 7: Stage-Gate kill (eliminar / pivotar al segmento 45-55 / perseverar)<br><br>Decisión 8: ¿Seguir criterios o juicio del campeón?'
                },
                {
                    number: 4,
                    title: 'External Ecosystem',
                    description: '<strong>Ecosistema Externo</strong><br><br>Buen Gusto recibe 3 propuestas simultáneas para inversión en innovación:<br><br>1. TecLab CDMX: packaging biodegradable (MXN 18M ask)<br><br>2. Fondo Narval CVC: AgriTech/FoodTech LATAM fund (MXN 80M ticket)<br><br>3. CINVESTAV: fermentation R&amp;D research (MXN 24M, CONAHCYT 30% tax credit eligible)<br><br>Decisión 9: Distribuir MXN 120M disponibles entre estas 3 opciones.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    wahs: 1.26,
                    npv: 3400,
                    governanceIntegrity: 0,
                    ambidexterityScore: null,
                    ecosystemScore: null,
                    wahsHistory: [1.26],
                    npvHistory: [3400],
                    killCount: 0,
                    vpResponse: 'b',
                    ambidexterityModel: 'b',
                    reportingStructure: 'b',
                    h3Concept: 'a',
                    mvpDesign: 'b',
                    stageGateDecision: 'a',
                    governanceChoice: 'a',
                    ecosystemAllocation: { teclab: 40, narval: 40, cinvestav: 40 },
                    randomEvent: null,
                    randomEventTriggered: {}
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    killCount: 3,
                    vpResponse: 'b',
                    ambidexterityModel: 'b',
                    reportingStructure: 'b',
                    h3Concept: 'a',
                    mvpDesign: 'b',
                    stageGate: 'a',
                    governanceChoice: 'a',
                    ecosystemAllocation: { teclab: 40, narval: 40, cinvestav: 40 }
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const currentPeriod = window.mySimulation.state.currentPeriod;

            if (currentPeriod === 1) {
                const killCount = parseInt(document.getElementById('killCountSlider').value);
                const vpResponse = document.querySelector('input[name="vpResponse"]:checked')?.value;
                if (!vpResponse) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('validation_error'), 'warning'
                    );
                    return false;
                }
                decisions.killCount = killCount;
                decisions.vpResponse = vpResponse;
            }

            if (currentPeriod === 2) {
                const ambidexterityModel = document.querySelector('input[name="ambidexterityModel"]:checked')?.value;
                const reportingStructure = document.querySelector('input[name="reportingStructure"]:checked')?.value;
                const h3Concept = document.querySelector('input[name="h3Concept"]:checked')?.value;

                if (!ambidexterityModel || !reportingStructure || !h3Concept) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('validation_error'), 'warning'
                    );
                    return false;
                }

                decisions.ambidexterityModel = ambidexterityModel;
                decisions.reportingStructure = reportingStructure;
                decisions.h3Concept = h3Concept;
            }

            if (currentPeriod === 3) {
                const mvpDesign = document.querySelector('input[name="mvpDesign"]:checked')?.value;
                const stageGate = document.querySelector('input[name="stageGate"]:checked')?.value;
                const governanceChoice = document.querySelector('input[name="governanceChoice"]:checked')?.value;

                if (!mvpDesign || !stageGate || !governanceChoice) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('validation_error'), 'warning'
                    );
                    return false;
                }

                decisions.mvpDesign = mvpDesign;
                decisions.stageGate = stageGate;
                decisions.governanceChoice = governanceChoice;
            }

            if (currentPeriod === 4) {
                const teclab = parseFloat(document.getElementById('tecLabAllocation').value) || 0;
                const narval = parseFloat(document.getElementById('narvalAllocation').value) || 0;
                const cinvestav = parseFloat(document.getElementById('cinvestavAllocation').value) || 0;

                const total = teclab + narval + cinvestav;

                if (Math.abs(total - 120) > 0.1) {
                    document.getElementById('allocationWarning').classList.remove('innov-sim-hidden');
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('allocation_error'), 'warning'
                    );
                    return false;
                }

                document.getElementById('allocationWarning').classList.add('innov-sim-hidden');
                decisions.ecosystemAllocation = { teclab, narval, cinvestav };
            }

            return true;
        }

        calculateResults(state) {
            const domainState = state.domainState;
            const decisions = state.decisions;
            const period = state.currentPeriod;

            let wahs = domainState.wahs;
            let npv = domainState.npv;
            let governanceIntegrity = domainState.governanceIntegrity;
            let ambidexterityScore = domainState.ambidexterityScore;
            let ecosystemScore = domainState.ecosystemScore;

            if (period === 1) {
                const killCount = decisions.killCount;
                domainState.killCount = killCount;
                domainState.vpResponse = decisions.vpResponse;

                wahs = 1.26 + (killCount * 0.08);
                npv = 3400 - (killCount * 120);

                if (decisions.vpResponse === 'b') {
                    governanceIntegrity = 1;
                } else if (decisions.vpResponse === 'c') {
                    governanceIntegrity = 0;
                }
            }

            if (period === 2) {
                domainState.ambidexterityModel = decisions.ambidexterityModel;
                domainState.reportingStructure = decisions.reportingStructure;
                domainState.h3Concept = decisions.h3Concept;

                let ambiScore = 55;
                if (decisions.ambidexterityModel === 'a') ambiScore = 85;
                else if (decisions.ambidexterityModel === 'b') ambiScore = 78;
                ambidexterityScore = ambiScore;

                let reportScore = 68;
                if (decisions.reportingStructure === 'b') reportScore = 82;
                else if (decisions.reportingStructure === 'c') reportScore = 72;
                ambidexterityScore = Math.round((ambidexterityScore + reportScore) / 2);
            }

            if (period === 3) {
                domainState.mvpDesign = decisions.mvpDesign;
                domainState.stageGateDecision = decisions.stageGate;
                domainState.governanceChoice = decisions.governanceChoice;

                if (decisions.stageGate === 'a' && decisions.governanceChoice === 'a') {
                    governanceIntegrity += 2;
                } else if (decisions.stageGate === 'b' && decisions.governanceChoice === 'a') {
                    governanceIntegrity += 1;
                } else if (decisions.governanceChoice === 'b') {
                    governanceIntegrity = Math.max(0, governanceIntegrity - 1);
                } else {
                    governanceIntegrity += 0.5;
                }

                if (Math.random() < 0.30 && !domainState.randomEventTriggered.R3) {
                    domainState.randomEvent = 'NutriLab launches same concept';
                    domainState.randomEventTriggered.R3 = true;
                }
            }

            if (period === 4) {
                const alloc = decisions.ecosystemAllocation;
                domainState.ecosystemAllocation = alloc;

                let allocScore = 50;
                if (Math.abs(alloc.teclab - 40) < 20 && Math.abs(alloc.narval - 40) < 20) {
                    allocScore = 75;
                }
                ecosystemScore = allocScore;

                if (Math.random() < 0.35 && !domainState.randomEventTriggered.R4a) {
                    domainState.randomEvent = 'CONAHCYT reduces tax credit from 30% to 20%';
                    domainState.randomEventTriggered.R4a = true;
                }

                if (Math.random() < 0.20 && !domainState.randomEventTriggered.R4b) {
                    domainState.randomEvent = 'Nestlé offers to acquire BGLabs';
                    domainState.randomEventTriggered.R4b = true;
                }
            }

            domainState.wahs = Math.min(3, wahs);
            domainState.npv = Math.max(1000, npv);
            domainState.governanceIntegrity = Math.min(3, governanceIntegrity);
            if (ambidexterityScore !== null) domainState.ambidexterityScore = ambidexterityScore;
            if (ecosystemScore !== null) domainState.ecosystemScore = ecosystemScore;

            domainState.wahsHistory.push(domainState.wahs);
            domainState.npvHistory.push(domainState.npv);

            // v1.1.0 FIX: persist a 0-100 score into domainState every period so the
            // grading/reporting layer can read it. results_utils.php
            // (express_resolveDomainScore) reads domainState.performance.overallScore
            // first, then top-level domainState.score. Without this the instructor
            // results panel shows an empty score. Same model as getPerformanceSummary.
            var _sc = this._computeScore(domainState);
            domainState.performance = { overallScore: _sc.total, grade: _sc.performance };
            domainState.score = _sc.total;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                wahs: domainState.wahs,
                npv: domainState.npv,
                governanceIntegrity: domainState.governanceIntegrity,
                ambidexterityScore,
                ecosystemScore,
                overallScore: _sc.total
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('wahsDisplay', 'domainState.wahs',
                (v) => v.toFixed(2));
            uiManager.bind('npvDisplay', 'domainState.npv',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('governanceDisplay', 'domainState.governanceIntegrity',
                (v) => Math.round(v) + '/3');
            uiManager.bind('ambidexterityDisplay', 'domainState.ambidexterityScore',
                (v) => v ? Math.round(v) + '/100' : '—');
            uiManager.bind('ecosystemDisplay', 'domainState.ecosystemScore',
                (v) => v ? Math.round(v) + '/100' : '—');
        }

        getChartConfig() {
            return {
                portfolioChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'WAHS',
                                data: [],
                                borderColor: '#2563eb',
                                backgroundColor: 'rgba(37, 99, 235, 0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y'
                            },
                            {
                                label: 'NPV (MXN M)',
                                data: [],
                                borderColor: '#059669',
                                backgroundColor: 'rgba(5, 150, 105, 0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Portfolio Health Trends' }
                        },
                        scales: {
                            y: { type: 'linear', display: true, position: 'left', title: { display: true, text: 'WAHS' } },
                            y1: { type: 'linear', display: true, position: 'right', title: { display: true, text: 'NPV (MXN M)' } }
                        }
                    }
                },
                kpiChart: {
                    type: 'bar',
                    data: {
                        labels: ['WAHS', 'NPV', 'Governance', 'Ambidexterity', 'Ecosystem'],
                        datasets: [{
                            label: 'KPI Scores',
                            data: [],
                            backgroundColor: ['#2563eb', '#059669', '#f59e0b', '#8b5cf6', '#ec4899'],
                            borderRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Final KPI Dashboard' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const labels = state.domainState.wahsHistory.map((_, i) => 'R' + (i + 1));
            const governanceNorm = (state.domainState.governanceIntegrity / 3) * 100;
            const ambidexNorm = state.domainState.ambidexterityScore || 0;
            const ecosystemNorm = state.domainState.ecosystemScore || 0;
            const wahsNorm = (state.domainState.wahs / 3) * 100;
            const npvNorm = Math.min(100, (state.domainState.npv / 4000) * 100);

            return {
                portfolioChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.wahsHistory },
                        { data: state.domainState.npvHistory }
                    ]
                },
                kpiChart: {
                    labels: ['WAHS', 'NPV', 'Governance', 'Ambidexterity', 'Ecosystem'],
                    datasets: [{
                        data: [wahsNorm, npvNorm, governanceNorm, ambidexNorm, ecosystemNorm]
                    }]
                }
            };
        }

        // v1.1.0: single source of truth for the 0-100 score, shared by
        // calculateResults() (persisted into domainState for grading/reporting)
        // and getPerformanceSummary() (completion modal). Thresholds UNCHANGED
        // from v1.0.0: WAHS>=1.80 +20, NPV>=3000 +25, governance==3 +25,
        // ambidexterity>=70 +15, ecosystem>=70 +15.
        _computeScore(ds) {
            ds = ds || {};
            let score = 0;
            if ((ds.wahs || 0) >= 1.80) score += 20;
            if ((ds.npv || 0) >= 3000) score += 25;
            if ((ds.governanceIntegrity || 0) === 3) score += 25;
            if ((ds.ambidexterityScore || 0) >= 70) score += 15;
            if ((ds.ecosystemScore || 0) >= 70) score += 15;
            let performance = 'Beginner';
            if (score >= 85) performance = 'Excellent';
            else if (score >= 70) performance = 'Good';
            else if (score >= 50) performance = 'Fair';
            return { total: score, performance: performance };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            const last = history[history.length - 1] || {};
            const r = last.results || {};
            const ds = last.domainState || {};
            const finalWAHS = (r.wahs != null ? r.wahs : (ds.wahs != null ? ds.wahs : 1.26));
            const finalNPV = (r.npv != null ? r.npv : (ds.npv != null ? ds.npv : 3400));
            const finalGovernance = (r.governanceIntegrity != null ? r.governanceIntegrity : (ds.governanceIntegrity || 0));
            const finalAmbi = (r.ambidexterityScore != null ? r.ambidexterityScore : (ds.ambidexterityScore || 0));
            const finalEco = (r.ecosystemScore != null ? r.ecosystemScore : (ds.ecosystemScore || 0));

            const sc = this._computeScore({
                wahs: finalWAHS, npv: finalNPV, governanceIntegrity: finalGovernance,
                ambidexterityScore: finalAmbi, ecosystemScore: finalEco
            });

            return {
                totalScore: sc.total,
                performance: sc.performance,
                finalWAHS,
                finalNPV,
                finalGovernance,
                insights: [
                    finalWAHS >= 1.80 ? 'Strong portfolio horizon balance' : 'Portfolio still weighted toward H1/H2',
