        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const idx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];

            const briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.description;

            document.querySelectorAll('.innov-sim-round-panel').forEach((panel, i) => {
                if (i + 1 === period) {
                    panel.classList.remove('innov-sim-hidden');
                } else {
                    panel.classList.add('innov-sim-hidden');
                }
            });

            const currentState = window.mySimulation?.state;
            if (currentState && currentState.domainState?.randomEvent) {
                const eventPanel = document.getElementById('randomEventsPanel');
                const eventMessage = document.getElementById('randomEventMessage');
                if (eventPanel && eventMessage) {
                    eventPanel.classList.remove('innov-sim-hidden');
                    eventMessage.innerHTML = '<strong>Event:</strong> ' + currentState.domainState.randomEvent;
                }
            }
        }
